function colLetter(n){let s=''; while(n>0){let m=(n-1)%26; s=String.fromCharCode(65+m)+s; n=(n-m-1)/26;} return s;}
const sh=ss.getSheetByName('Monthly Cohorts');
const startRow=8, endRow=171, startCol=7, endCol=122; // G:DR
const numRows=endRow-startRow+1, numCols=endCol-startCol+1;
const formulas=[];
for(let r=startRow;r<=endRow;r++){
  const row=[];
  for(let c=startCol;c<=endCol;c++){
    const dataColLetter=colLetter(c-3); // Data Set D:DO aligns to Monthly Cohorts G:DR
    row.push(`=SUMIF('Data Set'!$C$5:$C$220,$D${r},'Data Set'!$${dataColLetter}$5:$${dataColLetter}$220)`);
  }
  formulas.push(row);
}
sh.getRange(startRow,startCol,numRows,numCols).setFormulas(formulas);
SpreadsheetApp.flush();
log('Wrote formulas to '+sh.getRange(startRow,startCol,numRows,numCols).getA1Notation());
log(sh.getRange('G53:P56').getDisplayValues());
